        await ach('choque', 'p'); t = await pg.inner_text('#b-cond'); ck('bradi instável: atropina, marca-passo, adrenalina', 'Instável' in t and 'Atropina' in t and 'Marca-passo transcutâneo' in t and 'Adrenalina em bomba' in t and 'Agora: Atropina 1 mg' in t)
        await C('button.med:has-text("Atropina")'); m = await M(); ck('atropina não presume a ampola', 'apresentação da ampola' in m and '0,25 mg/1 mL' in m and '0,5 mg/1 mL' in m)
        await C('[data-a=cap][data-v="0"]'); ck('atropina 1 mg com ampola 0,25 = 4 mL, 4 ampolas', '4 mL' in await M() and '4 de 0,25 mg/1 mL' in await M())
        await C('[data-a=cap][data-v="1"]'); ck('atropina 1 mg com ampola 0,5 = 2 mL, 2 ampolas', '2 de 0,5 mg/1 mL' in await M()); await C('[data-a=madm]')
        ck('lembrete da próxima atropina', 'Atropina de novo a partir das' in await pg.inner_text('.lado'))
