        await C('button.med:has-text("Adrenalina em bomba")'); await C('[data-a=cprep][data-v="0"]'); await C('[data-a=cd][data-v="2"]'); ck('adrenalina 6 amp + 94 mL: 60 mcg/mL, 2 mcg/min = 2 mL/h', '60 mcg/mL' in await M() and '2 mL/h' in await M())
